layui.use(['layer','form'],function(){
	var form = layui.form
	$ = layui.jquery;
	(function (factory) {
		if (typeof define === 'function' && define.amd) {
			// AMD. Register as anonymous module.
			define(['jquery', 'ChineseDistricts'], factory);
		} else if (typeof exports === 'object') {
			// Node / CommonJS
			factory(require('jquery'), require('ChineseDistricts'));
		} else {
			// Browser globals.
			factory(jQuery, ChineseDistricts);
		}
	})
	var NAMESPACE = 'distpicker';
	var EVENT_CHANGE = 'change.' + NAMESPACE;
	var PROVINCE = 'province';
	var CIRY = 'city';
	var DISTRICT = 'district';
	var options = {
		province:'省份',
		city:'城市',
		district:'区县',
		spprovince:'省份',
		spcity:'城市',
		spdistrict:'区县',
		autoSelect: false
	}
	init = function(idName,pre=''){
		var $select = $('#'+idName).find('select');
		var data = {};
		var length = $select.length;
		$select.each(function () {
			$.extend(data, $(this).data());
		});
		$.each([pre+PROVINCE, pre+CIRY, pre+DISTRICT], $.proxy(function (i, type) {
			if (data[type]) {
				options[type] = data[type];
				this['$' + type] = $select.filter('[data-' + type + ']');
			} else {
				this['$' + type] = length > i ? $select.eq(i) : null;
			}
		}, this));
		
		// bind();
		bind(pre,function(data){});
		output(pre,PROVINCE)
		form.render('select');
	}
	bind = function(pre,callback){
		if(this.$province){
			output(pre,CIRY)
			output(pre,DISTRICT)
			form.render('select');
			form.on('select('+pre+PROVINCE+')',function(data){
				output(pre,CIRY)
				output(pre,DISTRICT)
				form.render('select');
			})
		}
		if(this.$city){
			output(pre,DISTRICT)
			form.render('select');
			form.on('select('+pre+CIRY+')',function(data){
				output(pre,DISTRICT)
				form.render('select');
			})
		}
	}
	getList = function (data,value) {
		var list = [];
		list.push(
			'<option' +
			' value=""' +
			' data-code=""' +
			'selected' +
			'>' +
			value +
			'</option>'
			);
		$.each(data, function (i, n) {
			list.push(
				'<option' +
				' value="' + (n.address && n.code ? n.address : '') + '"' +
				' data-code="' + (n.code || '') + '"' +
				(n.selected ? ' selected' : '') +
				'>' +
				(n.address || '') +
				'</option>'
				);
		});
		return list.join('');
	}
	output = function(pre,type){
		var data = [];
		var $select = $('select[name='+pre+type+']');
		code = (
			pre+type === pre+PROVINCE ? 86 :
			pre+type === pre+CIRY ? Number($('select[name='+pre+PROVINCE+']').find("option:selected").attr('data-code')) :
			pre+type === pre+DISTRICT ? Number($('select[name='+pre+CIRY+']').find("option:selected").attr('data-code')) : code
		);

		districts = $.isNumeric(code) ? ChineseDistricts[code] : null;
		value = options[pre+type];
		if ($.isPlainObject(districts)) {
			$.each(districts, function (code, address) {
				var selected = address === value;
				data.push({
					code: code,
					address: address,
					selected: selected
				});
			})
		}
		// $('#add-'+type).html(getList(data))
		$select.html(getList(data,value));
		// form.render('select');
	}
	init('cart-address-main','');
	init('cart-fpaddress-main','sp');
	form.render('select');
})